// Halide-based initialization of A and B, with an explicit schedule.
// We keep the original math but add parallel & vectorized execution.
static void init_array(int n,
                       Halide::Buffer<num_t, 1> A,
                       Halide::Buffer<num_t, 1> B) {
    Var i("i");
    Func init_A("init_A"), init_B("init_B");

