    // A[i] = ((DATA_TYPE) i + 2) / n;
    init_A(i) = cast<num_t>(i + 2) / cast<num_t>(n);

    // B[i] = ((DATA_TYPE) i + 3) / n;
    init_B(i) = cast<num_t>(i + 3) / cast<num_t>(n);

    // ---- Schedule for initialization ------------------------------------
    // This is cheap compared to the Jacobi time-stepping, but we still
    // vectorize and parallelize it so that large N initializes quickly.

    // Use the same JIT target that will be used for the main kernels,
    // so that natural_vector_size matches the actual CPU ISA in use.
    Target init_target = get_jit_target_from_environment();
    const int vec_width =
        init_target.natural_vector_size(type_of<num_t>());

    // Strip-mine 'i' into parallel tiles and vector lanes:
    Var io_A("io_A"), ii_A("ii_A");
    Var io_B("io_B"), ii_B("ii_B");
    const int init_tile_size = 1024;  // coarse tiling for good cache use

    init_A
        .compute_root()
        .split(i, io_A, ii_A, init_tile_size)
        .parallel(io_A)          // distribute tiles across cores
        .vectorize(ii_A, vec_width);  // vectorize within a tile

    init_B
        .compute_root()
        .split(i, io_B, ii_B, init_tile_size)
        .parallel(io_B)
        .vectorize(ii_B, vec_width);

    // Realize into the provided buffers.
    init_A.realize(A);
    init_B.realize(B);
}

