    // tuning constant; 1024 works well on modern CPUs and gives enough
    // work per task for our 32-core (64-thread) target.
    const int tile_size = 1024;

    Var ko_A("ko_A"), ki_A("ki_A");
    jacobi_A_to_B
        .compute_root()
        // k = ko_A * tile_size + ki_A
        .split(k, ko_A, ki_A, tile_size)
        .parallel(ko_A)              // parallel over tiles (outer loop)
        .vectorize(ki_A, vec_width); // vectorize within a tile

    Var ko_B("ko_B"), ki_B("ki_B");
    jacobi_B_to_A
        .compute_root()
        .split(k, ko_B, ki_B, tile_size)
        .parallel(ko_B)
        .vectorize(ki_B, vec_width);

